package com.novacommerce.order.application; import com.novacommerce.order.api.error.OrderException; import com.novacommerce.order.domain.order.*; import com.novacommerce.order.infrastructure.client.*; import com.novacommerce.order.infrastructure.client.InventoryClient.*; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service;
@Service public class CheckoutService{private final CheckoutTransactions tx;private final CatalogClient catalog;private final InventoryClient inventory;public CheckoutService(CheckoutTransactions t,CatalogClient c,InventoryClient i){tx=t;catalog=c;inventory=i;}public Result checkout(UUID owner,UUID cart,String key,String token){if(key==null||key.isBlank())throw new OrderException(HttpStatus.BAD_REQUEST,"IDEMPOTENCY_KEY_REQUIRED","Idempotency-Key is required");var snapshot=tx.snapshot(owner,cart);CustomerOrder order=tx.existing(owner,key,snapshot.hash());boolean replay=order!=null;if(order==null){var variants=catalog.variants(snapshot.lines().stream().map(CheckoutTransactions.Line::variantId).toList());order=tx.create(owner,key,snapshot,variants);}if(order.getStatus()!=OrderStatus.PENDING_INVENTORY)return new Result(order.getId(),order.getStatus(),false,replay);try{var reservation=inventory.reserve(order.getId(),snapshot.lines().stream().map(l->new InventoryClient.Item(l.variantId(),l.quantity())).toList(),token);CustomerOrder completed=tx.complete(order.getId(),reservation.id(),reservation.expiresAt());return new Result(completed.getId(),completed.getStatus(),false,replay);}catch(OrderException e){tx.inventoryFailed(order.getId());throw e;}catch(UnknownInventoryResultException e){return new Result(order.getId(),OrderStatus.PENDING_INVENTORY,true,true);}}public record Result(UUID orderId,OrderStatus status,boolean retryable,boolean replay){}}
